import * as React from "react";

import { useFieldControlAttributes } from "../lib/field-context";
import { Button } from "./button";

import geometry from "./button-geometry.module.css";
import styles from "./data.module.css";

export interface CopyButtonProps {
  value: string | (() => Promise<string>);
  label?: string;
  onCopy?: (value: string) => void;
  writeClipboard?: (value: string) => Promise<void>;
  disabled?: boolean;
  size?: "sm" | "md" | "lg";
  iconOnly?: boolean;
}
export async function writeClipboard(value: string): Promise<void> {
  if (!navigator.clipboard?.writeText) throw new Error("Clipboard access is unavailable.");
  await navigator.clipboard.writeText(value);
}
export function CopyButton({
  value,
  label = "Copy value",
  onCopy,
  writeClipboard: writer = writeClipboard,
  disabled,
  size = "sm",
  iconOnly = false
}: CopyButtonProps) {
  const [state, setState] = React.useState<"idle" | "pending" | "copied" | "failed">("idle");
  const turn = React.useRef(0);
  const pending = React.useRef(false);
  React.useEffect(() => {
    turn.current += 1;
    pending.current = false;
    setState("idle");
    return () => {
      turn.current += 1;
    };
  }, [typeof value === "string" ? value : null]);
  React.useEffect(() => {
    if (state !== "copied") return;
    const timer = window.setTimeout(() => setState("idle"), 1200);
    return () => window.clearTimeout(timer);
  }, [state]);
  const copy = async () => {
    if (pending.current) return;
    pending.current = true;
    turn.current += 1;
    const { current } = turn;
    setState("pending");
    try {
      const text = typeof value === "string" ? value : await value();
      await writer(text);
      if (current === turn.current) {
        setState("copied");
        onCopy?.(text);
      }
    } catch {
      if (current === turn.current) setState("failed");
    } finally {
      if (current === turn.current) pending.current = false;
    }
  };
  return (
    <span
      className={`${styles.copy} ${styles[`copy${size}`]}`}
      data-slot="copy-button"
      data-size={size}
      data-copy-state={state}
    >
      <Button
        type="button"
        variant="ghost"
        className={geometry.nestedAction}
        iconOnly={iconOnly}
        icon={iconOnly ? (state === "copied" ? "check" : "copy") : undefined}
        title={iconOnly ? (state === "copied" ? "Copied" : label) : undefined}
        disabled={disabled}
        loading={state === "pending"}
        onClick={() => copy()}
      >
        {state === "copied" ? "Copied" : label}
      </Button>
      <span
        role="status"
        data-copy-feedback
        className={state === "failed" ? styles.smallStatus : styles.sr}
      >
        {state === "failed" ? "Copy failed. Try again." : state === "copied" ? "Copied" : ""}
      </span>
    </span>
  );
}
export interface SecretValueProps {
  value: string;
  copyable?: boolean;
  label?: string;
  onCopy?: CopyButtonProps["onCopy"];
  id?: string;
  "aria-describedby"?: string;
  "aria-invalid"?: boolean;
}
export function SecretValue({
  value,
  copyable = true,
  label = "Secret value",
  onCopy,
  id,
  ...aria
}: SecretValueProps) {
  const control = useFieldControlAttributes({ ...(id ? { id } : {}), ...aria });
  const [revealed, setRevealed] = React.useState<string | null>(null);
  React.useEffect(() => setRevealed(null), [value]);
  const shown = revealed === value;
  return (
    <div className={styles.secret}>
      <span
        role="textbox"
        aria-readonly
        aria-label={label}
        title={shown ? value : undefined}
        {...control}
        className={styles.machine}
      >
        {shown ? value : "••••••••"}
      </span>
      <Button
        type="button"
        variant="ghost"
        className={geometry.nestedAction}
        iconOnly
        icon="eye"
        title={shown ? "Hide value" : "Reveal value"}
        aria-pressed={shown}
        onClick={() => setRevealed(shown ? null : value)}
      >
        {shown ? "Hide value" : "Reveal value"}
      </Button>
      {copyable && <CopyButton value={value} onCopy={onCopy} iconOnly />}
    </div>
  );
}
export interface StoredSecret {
  id: string;
  revision: string;
  hasValue: boolean;
}
export interface SensitiveEditorProps {
  stored: StoredSecret;
  label: string;
  multiline?: boolean;
  readOnly?: boolean;
  onReveal?: (context: { signal: AbortSignal }) => Promise<string>;
  onSave?: (value: string, context: { signal: AbortSignal; stored: StoredSecret }) => Promise<void>;
  onCopy?: CopyButtonProps["onCopy"];
  copyable?: boolean;
}
type View =
  | { kind: "masked" }
  | { kind: "loading" }
  | { kind: "revealed"; value: string }
  | { kind: "failed" };
export function SensitiveEditor({
  stored,
  label,
  multiline = false,
  readOnly = false,
  onReveal,
  onSave,
  onCopy,
  copyable = true
}: SensitiveEditorProps) {
  // Identity keys discard plaintext before a new stored object can render.
  return (
    <SensitiveEditorSession
      key={`${stored.id}:${stored.revision}:${stored.hasValue}:${Boolean(onReveal)}:${Boolean(onSave)}:${readOnly}`}
      stored={stored}
      label={label}
      multiline={multiline}
      readOnly={readOnly}
      onReveal={onReveal}
      onSave={onSave}
      onCopy={onCopy}
      copyable={copyable}
    />
  );
}
function SensitiveEditorSession({
  stored,
  label,
  multiline,
  readOnly,
  onReveal,
  onSave,
  onCopy,
  copyable
}: SensitiveEditorProps) {
  const [view, setView] = React.useState<View>({ kind: "masked" });
  const [draft, setDraft] = React.useState<string | null>(null);
  const [saving, setSaving] = React.useState(false);
  const [notice, setNotice] = React.useState({ message: "", failed: false });
  const { message, failed } = notice;
  const setMessage = (text: string, error = false) => setNotice({ message: text, failed: error });
  const controller = React.useRef<AbortController | null>(null);
  const request = React.useRef(0);
  const savingRef = React.useRef(false);
  const uid = React.useId();
  const editRef = React.useRef<HTMLTextAreaElement>(null);
  const region = React.useRef<HTMLDivElement>(null);
  React.useEffect(
    () => () => {
      request.current += 1;
      controller.current?.abort();
    },
    []
  );
  React.useEffect(() => {
    if (draft !== null) editRef.current?.focus();
  }, [draft === null]);
  const hide = () => {
    request.current += 1;
    controller.current?.abort();
    setView({ kind: "masked" });
  };
  const reveal = async () => {
    if (!onReveal || view.kind === "loading") return;
    request.current += 1;
    const { current } = request;
    controller.current?.abort();
    const next = new AbortController();
    controller.current = next;
    setView({ kind: "loading" });
    setMessage("");
    try {
      const value = await onReveal({ signal: next.signal });
      if (request.current === current && !next.signal.aborted) setView({ kind: "revealed", value });
    } catch {
      if (request.current === current && !next.signal.aborted) {
        setView({ kind: "failed" });
        setMessage("The value could not be revealed. Check access and try again.", true);
      }
    }
  };
  const save = async () => {
    if (draft === null || !onSave || savingRef.current) return;
    request.current += 1;
    const { current } = request;
    controller.current?.abort();
    const next = new AbortController();
    controller.current = next;
    savingRef.current = true;
    setSaving(true);
    setMessage("Saving replacement");
    try {
      await onSave(draft, { signal: next.signal, stored });
      if (request.current === current && !next.signal.aborted) {
        setDraft(null);
        setView({ kind: "masked" });
        setMessage("Replacement saved");
        region.current?.focus();
      }
    } catch {
      if (request.current === current && !next.signal.aborted) {
        setMessage("The replacement was not saved. Your draft is kept. Retry or cancel.", true);
      }
    } finally {
      if (request.current === current) {
        savingRef.current = false;
        setSaving(false);
      }
    }
  };
  return (
    <div
      className={styles.editor}
      role="group"
      ref={region}
      tabIndex={-1}
      aria-label={label}
      data-v4-escape-owner={
        draft !== null || view.kind === "loading" || view.kind === "revealed" ? "" : undefined
      }
      onKeyDown={(event) => {
        if (
          event.key === "Escape" &&
          !saving &&
          (draft !== null || view.kind === "loading" || view.kind === "revealed")
        ) {
          event.preventDefault();
          event.stopPropagation();
          setDraft(null);
          hide();
          setMessage("Edit cancelled");
          region.current?.focus();
        }
      }}
    >
      <label className={styles.label} htmlFor={draft !== null ? uid : undefined}>
        {label}
      </label>
      {draft !== null ? (
        <textarea
          id={uid}
          ref={editRef}
          rows={multiline ? 3 : 1}
          aria-describedby={`${uid}-status`}
          placeholder="New value"
          value={draft}
          disabled={saving}
          autoComplete="off"
          spellCheck={false}
          onChange={(event) => {
            setDraft(event.target.value);
            setMessage("");
          }}
          className={styles.editorInput}
        />
      ) : (
        <div className={styles.secret} data-multiline={multiline || undefined}>
          <span
            className={styles.machine}
            title={view.kind === "revealed" ? view.value : undefined}
            aria-label={
              view.kind === "revealed"
                ? undefined
                : stored.hasValue
                  ? "Stored value is hidden"
                  : "No stored value"
            }
          >
            {view.kind === "revealed" ? view.value : stored.hasValue ? "••••••••" : "No value"}
          </span>
          <Button
            type="button"
            variant="ghost"
            className={geometry.nestedAction}
            iconOnly
            icon="eye"
            title={
              !onReveal
                ? "You do not have permission to view this value"
                : !stored.hasValue
                  ? "No stored value"
                  : view.kind === "revealed"
                    ? "Hide value"
                    : "Reveal value"
            }
            disabled={!onReveal || !stored.hasValue}
            loading={view.kind === "loading"}
            aria-pressed={view.kind === "revealed"}
            onClick={() => (view.kind === "revealed" ? hide() : reveal())}
          >
            {view.kind === "revealed" ? "Hide value" : "Reveal value"}
          </Button>
          {copyable && (
            <CopyButton
              value={
                view.kind === "revealed"
                  ? view.value
                  : () =>
                      onReveal
                        ? onReveal({ signal: new AbortController().signal })
                        : Promise.reject()
              }
              onCopy={onCopy}
              disabled={!onReveal || !stored.hasValue}
              iconOnly
            />
          )}
        </div>
      )}
      {(draft !== null || stored.hasValue || onSave) && (
        <div className={styles.editorActions}>
          {draft !== null ? (
            <>
              <Button
                type="button"
                variant="outline"
                disabled={saving}
                onClick={() => {
                  setDraft(null);
                  hide();
                  setMessage("Edit cancelled");
                  region.current?.focus();
                }}
              >
                Cancel
              </Button>
              <Button type="button" loading={saving} onClick={() => save()}>
                Save replacement
              </Button>
            </>
          ) : (
            <Button
              type="button"
              variant="outline"
              disabled={readOnly || !onSave}
              title={
                readOnly || !onSave ? "You do not have permission to change this value" : undefined
              }
              onClick={() => {
                setDraft("");
                hide();
                setMessage("");
              }}
            >
              Replace without viewing
            </Button>
          )}
        </div>
      )}
      <div id={`${uid}-status`} role="status" className={failed ? styles.editorError : styles.sr}>
        {message}
      </div>
    </div>
  );
}

.button {
  --v4-action-requested-height: var(--v4-size-control-default);
  --v4-action-height: var(--v4-action-requested-height);
  --v4-action-font-size: var(--v4-type-label-font-size);
  --v4-action-line-height: var(--v4-type-label-line-height);
  --v4-action-inset: var(--v4-space-control-inline);
  --v4-action-icon-size: var(--v4-size-icon);
  --v4-kbd-host-block: calc(var(--v4-action-height) - 2 * var(--v4-size-control-border));
  --v4-kbd-host-end: var(--v4-action-inset);
  box-sizing: border-box;
  min-height: var(--v4-action-height);
  gap: var(--v4-space-control-gap);
  padding-block: calc(
    (var(--v4-action-height) - var(--v4-action-line-height)) / 2 - var(--v4-size-control-border)
  );
  padding-inline: var(--v4-action-inset);
  border-width: var(--v4-size-control-border);
  border-radius: 0;
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-action-font-size);
  line-height: var(--v4-action-line-height);
  font-weight: var(--v4-type-label-font-weight);
  letter-spacing: var(--v4-type-label-letter-spacing);
  cursor: default;
}
.default {
  --v4-action-icon-size: var(--v4-size-icon-sm);
  --v4-action-requested-height: var(--v4-size-control-default);
  --v4-action-inset: var(--v4-space-control-inline-sm);
}
.regular {
  --v4-action-requested-height: var(--v4-size-control-md);
}
.large {
  --v4-action-requested-height: var(--v4-size-control-lg);
  --v4-action-inset: var(--v4-space-16);
}
.extraSmall,
.iconExtraSmall {
  --v4-action-requested-height: var(--v4-size-control-xs);
  --v4-action-icon-size: var(--v4-size-icon-xs);
  --v4-action-font-size: var(--v4-type-caption-font-size);
  --v4-action-line-height: var(--v4-type-caption-line-height);
  --v4-action-inset: var(--v4-space-6);
}
.icon {
  --v4-action-requested-height: var(--v4-size-nested-lg);
}
.iconSmall {
  --v4-action-requested-height: var(--v4-size-nested-md);
}
.iconLarge {
  --v4-action-requested-height: var(--v4-size-control-lg);
}
.iconRow {
  --v4-action-requested-height: var(--v4-size-target-row);
  --v4-action-icon-size: var(--v4-size-glyph);
}
.icon,
.iconExtraSmall,
.iconSmall,
.iconLarge,
.iconRow,
.iconOnly {
  width: var(--v4-action-height);
  min-width: var(--v4-action-height);
  padding-inline: 0;
}
.button svg:not([class*="size-"]) {
  width: var(--v4-action-icon-size);
  height: var(--v4-action-icon-size);
}
.inputGroup {
  --v4-nested-action-height: var(--v4-size-nested-default);
}
.inputGroup[data-size="xs"] {
  --v4-nested-action-height: var(--v4-field-nested);
}
.inputGroup[data-size="sm"] {
  --v4-nested-action-height: var(--v4-size-nested-sm);
}
.inputGroup[data-size="md"] {
  --v4-nested-action-height: var(--v4-size-nested-md);
}
.inputGroup[data-size="lg"] {
  --v4-nested-action-height: var(--v4-size-nested-lg);
}
.nestedAction {
  --v4-action-height: min(
    var(--v4-action-requested-height),
    var(--v4-nested-action-height, var(--v4-action-requested-height))
  );
}
.inputGroup > [data-slot="input-group-addon"][data-align="inline-start"][data-has-button] {
  padding-inline-start: var(--v4-space-control-slot-inset);
}
.inputGroup > [data-slot="input-group-addon"][data-align="inline-end"][data-has-button] {
  padding-inline-end: var(--v4-space-control-slot-inset);
}
.badged[data-v4-button] {
  position: relative;
  overflow: visible;
}
.cornerBadge {
  position: absolute;
  top: calc(var(--v4-size-control-border) / -2);
  inset-inline-end: calc(-1 * var(--v4-size-control-border));
  z-index: 1;
  display: inline-flex;
  translate: 0 -50%;
  background: var(--v4-surface);
  pointer-events: none;
}
.triggerLayout {
  justify-content: flex-start;
  text-align: start;
}
.triggerLayout.regular {
  --v4-action-inset: var(--v4-space-control-inline-md);
}
.triggerLayout.large {
  --v4-action-inset: var(--v4-space-control-inline);
}
[data-v4-button].triggerLayout > [data-press],
.triggerLayout > [data-press] > [data-slot="button-label-group"] {
  display: flex;
  flex: 1 1 auto;
  justify-content: flex-start;
  width: 100%;
}
.triggerLabel {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.triggerLayout svg.triggerChevron {
  width: var(--v4-size-icon);
  height: var(--v4-size-icon);
}
.triggerLayout:is([data-variant="outline"], [data-variant="secondary"], [data-variant="ghost"])
  .triggerChevron {
  color: var(--v4-muted);
}

.gridShell,
.tableShell,
.listShell {
  color: var(--v4-ink);
}
.gridScroll,
/* v4-check-ignore scroll-fade -- the edge fade comes from data-scroll-fade on this element */
.tableScroll {
  border-radius: 0;
  overflow: auto;
  position: relative;
}
.tableScroll {
  scroll-padding-block: var(--v4-focus-clearance);
}
.gridScroll {
  background: var(--v4-surface);
  border: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridScroll {
  font-family: var(--v4-type-mono-font-family);
  font-size: var(--v4-type-mono-font-size);
  line-height: var(--v4-type-mono-line-height);
  font-weight: var(--v4-type-mono-font-weight);
  letter-spacing: var(--v4-type-mono-letter-spacing);
}
.tree:focus-visible {
  outline: 2px solid var(--v4-ink);
  outline-offset: -2px;
}
.gridScroll[aria-activedescendant]:focus-visible {
  outline: none;
}
.gridRow,
.gridHead {
  display: grid;
  width: max-content;
  min-width: 100%;
}
.gridRow {
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridRow[data-last] {
  border-bottom-color: transparent;
}
/* With a footer the grid is a framed shell: the borderless tint frame holds the inset
   grid on top and the footer below, so there is exactly one edge at the bottom. */
.gridShell[data-footer] {
  --v4-frame-pad: var(--v4-space-3);
  padding: var(--v4-frame-pad) var(--v4-frame-pad) 0;
  background: var(--v4-tint);
  border-radius: 0;
}
.gridShell[data-footer] > .gridScroll {
  border-radius: 0;
  box-shadow: var(--v4-shadow-raised);
}
.gridShell[data-footer] > .status,
.gridShell[data-footer] > .actions {
  padding-inline: var(--v4-space-8);
}
.gridFooter {
  display: flex;
  align-items: center;
  gap: var(--v4-space-12);
  min-height: var(--v4-space-40);
  padding: var(--v4-space-4) var(--v4-space-8);
  color: var(--v4-muted);
  font-family: var(--v4-type-caption-font-family);
  font-size: var(--v4-type-caption-font-size);
  line-height: var(--v4-type-caption-line-height);
  font-variant-numeric: tabular-nums;
}
.gridAddHeader {
  display: flex;
  align-items: center;
  padding-inline: var(--v4-space-4);
}
.gridAddForm {
  display: grid;
  gap: var(--v4-space-6);
  font-family: var(--v4-type-small-font-family);
  font-size: var(--v4-type-small-font-size);
  line-height: var(--v4-type-small-line-height);
}
.gridAddCheck {
  display: flex;
  align-items: center;
  gap: var(--v4-space-8);
  margin-top: var(--v4-space-4);
}
.gridAddActions {
  display: flex;
  justify-content: flex-end;
  gap: var(--v4-space-8);
  margin-top: var(--v4-space-8);
}
.gridKey {
  flex: none;
  color: var(--v4-muted);
}
.gridHead {
  position: sticky;
  top: 0;
  z-index: 2;
  background: var(--v4-paper);
  min-height: var(--v4-size-control-sm);
  border-bottom: var(--v4-size-control-border) solid var(--v4-line-soft);
  color: var(--v4-muted);
}
.gridHeader {
  position: relative;
  display: flex;
  align-items: center;
  gap: 0;
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
  padding: 0 var(--v4-space-12) 0 0;
  overflow: visible;
}
.gridHeader[data-selected] {
  background: var(--v4-select);
  color: var(--v4-ink);
}
.gridHeaderLabel {
  display: flex;
  flex: 1;
  min-width: 0;
  align-items: center;
  gap: var(--v4-space-6);
  padding-inline: var(--v4-space-8);
  overflow: hidden;
}
.gridHeaderLabel > span {
  display: inline-flex;
  align-items: center;
  gap: var(--v4-space-4);
  color: var(--v4-ink);
  font-family: var(--v4-type-label-font-family);
  font-size: var(--v4-type-label-font-size);
  line-height: var(--v4-type-label-line-height);
  font-weight: var(--v4-type-label-font-weight);
  letter-spacing: var(--v4-type-label-letter-spacing);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridHeader small {
  min-width: 0;
  overflow: hidden;
  color: var(--v4-muted);
  font-family: var(--v4-type-mono-sm-font-family);
  font-size: var(--v4-type-mono-sm-font-size);
  line-height: var(--v4-type-mono-sm-line-height);
  font-weight: var(--v4-type-mono-sm-font-weight);
  text-overflow: ellipsis;
  white-space: nowrap;
}
.gridSort[data-active] {
  color: var(--v4-ink);
}
.gridSort:not([data-active]) {
  opacity: 0;
}
.gridHeader:is(:hover, :focus-within) > .gridSort {
  opacity: 1;
}
.gutter {
  position: sticky;
  left: 0;
  z-index: 1;
  background: var(--v4-surface);
  padding: var(--v4-space-6) var(--v4-space-8);
  min-width: var(--v4-space-40);
  text-align: right;
  color: var(--v4-faint);
  border-right: var(--v4-size-control-border) solid var(--v4-line-soft);
}
.gridHead > .gutter {
  background: inherit;
}
.gutter[data-selected] {
  background: var(--v4-select);
  color: var(--v4-ink);
}
.gutter button {
  font: inherit;
  color: inherit;
  background: none;
